import 'package:drift/drift.dart';

import '../../database/database.dart';

// Shot including its curve ↔ `data` in the sync event.
//
// Fields via the JSON form generated by drift (times as Unix ms) so new
// columns aren't forgotten — except the local ones: int IDs, image paths
// (photos are handled separately), the raw debug file and the sync columns
// themselves. The bean is stored as its syncId.
//
// The curve goes column-wise: {"timeMs":[…],"pressure":[…],…}; columns
// that are empty throughout are dropped. That compresses well (gzip in the
// envelope) — real shots end up at ~6 KB, the largest at ~24 KB.

const shotType = 'shot';

const _localShotFields = {
  'id',
  'beanId',
  'shotPhotoPath',
  'profileImagePath',
  'rawDebugJson',
  'syncId',
  'updatedAt',
  'deviceId',
  'syncState',
};

const _localReadingFields = {'id', 'shotId'};

Map<String, Object?> shotToSyncData(
  Shot shot, {
  required String? beanSyncId,
  required List<ShotReading> readings,
}) {
  if (shot.deletedAt != null) return shotTombstoneData(shot);
  final json = shot.toJson()
    ..removeWhere((key, _) => _localShotFields.contains(key));
  json['beanSyncId'] = beanSyncId;
  json['readings'] = readingsToColumns(readings);
  return json;
}

/// What a deleted shot sends along: enough to create the row and prevent
/// re-importing it from the machine.
Map<String, Object?> shotTombstoneData(Shot shot) => {
  'timestamp': shot.timestamp.millisecondsSinceEpoch,
  'externalId': shot.externalId,
  'machine': shot.machine,
};

/// Throws [FormatException] if required fields are missing or types don't
/// match.
({
  ShotsCompanion shot,
  String? beanSyncId,
  List<ShotReadingsCompanion Function(int)> readings,
})
shotFromSyncData(Map<String, Object?> data, {required bool deleted}) {
  if (deleted) {
    final ts = data['timestamp'];
    if (ts is! int) throw const FormatException('Shot tombstone without time');
    return (
      shot: ShotsCompanion(
        timestamp: Value(DateTime.fromMillisecondsSinceEpoch(ts)),
        externalId: Value(data['externalId'] as String?),
        machine: data['machine'] is String
            ? Value(data['machine'] as String)
            : const Value.absent(),
      ),
      beanSyncId: null,
      readings: const [],
    );
  }
  final json = Map<String, Object?>.from(data);
  final beanSyncId = json.remove('beanSyncId');
  final columns = json.remove('readings');
  final Shot shot;
  try {
    shot = Shot.fromJson({
      ...json,
      'id': 0,
      'beanId': null,
      'shotPhotoPath': null,
      'profileImagePath': null,
      'rawDebugJson': null,
      'syncId': '',
      'updatedAt': 0,
      'deviceId': null,
      'syncState': SyncState.synced,
    });
  } catch (e) {
    throw FormatException('Shot data does not fit: $e');
  }
  final companion = shot
      .toCompanion(true)
      .copyWith(
        id: const Value.absent(),
        beanId: const Value.absent(),
        shotPhotoPath: const Value.absent(),
        profileImagePath: const Value.absent(),
        rawDebugJson: const Value.absent(),
        syncId: const Value.absent(),
        updatedAt: const Value.absent(),
        deviceId: const Value.absent(),
        syncState: const Value.absent(),
      );
  return (
    shot: companion,
    beanSyncId: beanSyncId is String ? beanSyncId : null,
    readings: columns is Map
        ? readingsFromColumns(Map<String, Object?>.from(columns))
        : const [],
  );
}

Map<String, List<Object?>> readingsToColumns(List<ShotReading> rows) {
  final columns = <String, List<Object?>>{};
  for (var i = 0; i < rows.length; i++) {
    final json = rows[i].toJson();
    for (final entry in json.entries) {
      if (_localReadingFields.contains(entry.key)) continue;
      columns.putIfAbsent(
        entry.key,
        () => List<Object?>.filled(rows.length, null),
      )[i] = entry.value;
    }
  }
  columns.removeWhere((_, values) => values.every((v) => v == null));
  return columns;
}

List<ShotReadingsCompanion Function(int)> readingsFromColumns(
  Map<String, Object?> columns,
) {
  final lists = <String, List<Object?>>{
    for (final entry in columns.entries)
      if (entry.value is List) entry.key: entry.value! as List<Object?>,
  };
  final length = lists['timeMs']?.length ?? 0;
  if (lists.values.any((l) => l.length != length)) {
    throw const FormatException('Reading columns differ in length');
  }
  // Columns that were empty at the sender are missing — fromJson still
  // needs them as null.
  final empty = {
    for (final key in const ShotReading(
      id: 0,
      shotId: 0,
      timeMs: 0,
    ).toJson().keys)
      if (!_localReadingFields.contains(key)) key: null,
  };
  final result = <ShotReadingsCompanion Function(int)>[];
  for (var i = 0; i < length; i++) {
    final ShotReading reading;
    try {
      reading = ShotReading.fromJson({
        ...empty,
        for (final entry in lists.entries) entry.key: entry.value[i],
        'id': 0,
        'shotId': 0,
      });
    } catch (e) {
      throw FormatException('Reading $i does not fit: $e');
    }
    final companion = reading
        .toCompanion(true)
        .copyWith(id: const Value.absent());
    result.add((shotId) => companion.copyWith(shotId: Value(shotId)));
  }
  return result;
}
